from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()
model = None

class Req(BaseModel):
    features: list[float]

@app.get("/readyz")
def ready():
    if model is None:
        raise HTTPException(503, "model not loaded")
    return {"status": "ready"}

@app.post("/v1/models/churn:predict")
def predict(req: Req):
    score = model.predict([req.features])[0]
    return {"score": float(score), "model_version": "3"}
